sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 red;
layout(color) uniform half4 green;
layout(color) uniform half4 blue;
uniform float gammaRed;
uniform float gammaGreen;
uniform float gammaBlue;
uniform float offset;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return half4(0.0);
    float3 f = float3(c.rgb) / float(c.a);
    float3 m = f.r * float3(red.rgb) + f.g * float3(green.rgb) + f.b * float3(blue.rgb);
    m = pow(max(m, 0.0), 1.0 / max(float3(gammaRed, gammaGreen, gammaBlue), float3(0.01))) + offset;
    return half4(half3(clamp(m, 0.0, 1.0)) * c.a, c.a);
}
